import React, { useState } from 'react';
import './Booking.css';
import { useNavigate } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';

export default function RestaurantBooking() {
  const [formData, setFormData] = useState({
    location: '',
    cuisine: '',
    date: '',
    time: '',
    partySize: ''
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');
    try {
      const response = await fetch('/api/tables', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      const data = await response.json();

      if (data.length > 0) {
        navigate('/results', { state: { tables: data } });
      } else {
        setMessage('عذرًا، لا توجد طاولات متاحة.');
      }
    } catch (error) {
      setMessage('حدث خطأ أثناء البحث.');
    } finally {
      setLoading(false);
    }
  };

  return (  
    <div className="background-image">
        <h1 className="text-center mb-5 text-white fw-bold">BOOK A TABLE</h1>
      <div className="container booking-container">
      

        {message && (
          <div className={`alert ${message.includes('خطأ') ? 'alert-danger' : 'alert-success'}`}>
            {message}
          </div>
        )}

        <form onSubmit={handleSearch}>
          <div className="row g-4">
            <div className="col-md-2">
              <label className="form-label text-dark">Location:</label>
              <input
                type="text"
                name="location"
                className="form-control"
                placeholder="اختر الموقع"
                value={formData.location}
                onChange={handleInputChange}
                required
              />
            </div>

            <div className="col-md-2">
              <label className="form-label text-dark">Cuisine:</label>
              <input
                type="text"
                name="cuisine"
                className="form-control"
                placeholder="نوع المطبخ"
                value={formData.cuisine}
                onChange={handleInputChange}
                required
              />
            </div>

            <div className="col-md-2">
              <label className="form-label text-dark">Date:</label>
              <input
                type="date"
                name="date"
                className="form-control"
                value={formData.date}
                onChange={handleInputChange}
                min={new Date().toISOString().split('T')[0]}
                required
              />
            </div>

            <div className="col-md-2">
              <label className="form-label text-dark">Time:</label>
              <input
                type="time"
                name="time"
                className="form-control"
                value={formData.time}
                onChange={handleInputChange}
                required
              />
            </div>

            <div className="col-md-2">
              <label className="form-label text-dark">Party Size:</label>
              <input
                type="number"
                name="partySize"
                className="form-control"
                min="1"
                placeholder="عدد الأشخاص"
                value={formData.partySize}
                onChange={handleInputChange}
                required
              />
            </div>

            <div className="col-md-2 d-flex align-items-end">
              <button type="submit" className="btn btn-light-green w-100" disabled={loading}>
                {loading ? 'جاري البحث...' : 'SEARCH'}
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}
